1	'use strict';
2	// MCP authentication surface: OIDC discovery, JWKS, token validation and the Bearer
3	// middleware. Extracted from eventhandler.js so it can be reasoned about and unit-tested
4	// in isolation. All external dependencies (HTTP, logging, and the jose primitives) are
5	// injectable, so tests need neither a live IdP nor a running Node-RED.
6	
7	const crypto = require('crypto');
8	const jose   = require('jose');
9	
10	const TOKEN_CACHE_MAX = 1000;
11	
12	// Constant-time secret comparison that does not leak length. Both inputs are hashed to a
13	// fixed-width digest before timingSafeEqual, so mismatched lengths compare safely.
14	function secretEqual(a, b) {
15	    const ha = crypto.createHash('sha256').update(String(a)).digest();
16	    const hb = crypto.createHash('sha256').update(String(b)).digest();
17	    return crypto.timingSafeEqual(ha, hb);
18	}
19	
20	function createMcpAuth(opts) {
21	    const {
22	        issuerUrl          = '',
23	        tokenTTL           = 300000,
24	        tokenAudience      = '',
25	        localDebugToken    = '',
26	        mcpServerUrl       = '',
27	        httpGet,
28	        log                = () => {},
29	        warn               = () => {},
30	        // Injectable for tests; default to the real jose primitives.
31	        jwtVerify          = jose.jwtVerify,
32	        createRemoteJWKSet = jose.createRemoteJWKSet
33	    } = opts || {};
34	
35	    if (typeof httpGet !== 'function') {
36	        throw new Error('createMcpAuth requires an httpGet function');
37	    }
38	
39	    let tokenCache = {};
40	    let oidcConfig = null, oidcConfigPromise = null;
41	    let jwks = null;
42	
43	    // OIDC discovery with PocketID-style fallback paths. Discover the IdP's real endpoints
44	    // from /.well-known/openid-configuration so any spec-compliant OIDC provider works; fall
45	    // back to the PocketID path layout when discovery is unavailable.
46	    function fallbackEndpoints() {
47	        return {
48	            issuer                 : issuerUrl,
49	            authorization_endpoint : issuerUrl + '/authorize',
50	            token_endpoint         : issuerUrl + '/api/oidc/token',
51	            userinfo_endpoint      : issuerUrl + '/api/oidc/userinfo',
52	            jwks_uri               : issuerUrl + '/.well-known/jwks.json'
53	        };
54	    }
55	
56	    function getOidcConfig() {
57	        if (oidcConfig) return Promise.resolve(oidcConfig);
58	        if (!oidcConfigPromise) {
59	            oidcConfigPromise = (async () => {
60	                const fb = fallbackEndpoints();
61	                if (!issuerUrl) { oidcConfig = fb; return fb; }
62	                try {
63	                    const r = await httpGet(issuerUrl + '/.well-known/openid-configuration', {});
64	                    if (r.status === 200 && r.body && typeof r.body === 'object' && r.body.jwks_uri) {
65	                        oidcConfig = Object.assign(fb, r.body);   // discovered values win, per-field fallback
66	                        log('MCP OIDC discovery ok: issuer=' + oidcConfig.issuer);
67	                    } else {
68	                        warn('MCP OIDC discovery returned ' + r.status + ' — using fallback endpoint paths');
69	                        oidcConfig = fb;
70	                    }
71	                } catch (e) {
72	                    warn('MCP OIDC discovery failed: ' + e.message + ' — using fallback endpoint paths');
73	                    oidcConfig = fb;
74	                }
75	                return oidcConfig;
76	            })();
77	        }
78	        return oidcConfigPromise;
79	    }
80	
81	    // Lazy JWKS — built from the discovered jwks_uri on first real token validation.
82	    async function getJwks() {
83	        if (!jwks) {
84	            const oidc = await getOidcConfig();
85	            jwks = createRemoteJWKSet(new URL(oidc.jwks_uri));
86	        }
87	        return jwks;
88	    }
89	
90	    // Insert into the token cache with a hard size cap: drop expired entries first, then evict
91	    // the soonest-to-expire until back under the cap. Prevents unbounded growth (and OOM) from
92	    // a flood of unique tokens on an internet-exposed endpoint.
93	    function cacheToken(key, entry) {
94	        tokenCache[key] = entry;
95	        const keys = Object.keys(tokenCache);
96	        if (keys.length <= TOKEN_CACHE_MAX) return;
97	        const now = Date.now();
98	        for (const k of keys) { if (tokenCache[k].exp < now) delete tokenCache[k]; }
99	        let remaining = Object.keys(tokenCache);
100	        if (remaining.length > TOKEN_CACHE_MAX) {
101	            remaining.sort((x, y) => tokenCache[x].exp - tokenCache[y].exp);
102	            for (let i = 0; i < remaining.length - TOKEN_CACHE_MAX; i++) delete tokenCache[remaining[i]];
103	        }
104	    }
105	
106	    async function validateToken(token) {
107	        // Local debug token bypass — skips the IdP entirely. Constant-time compare so the token
108	        // can't be recovered by timing the response.
109	        if (localDebugToken && secretEqual(token, localDebugToken)) {
110	            return { sub: 'debug', name: 'Local debug user', groups: ['admin'] };
111	        }
112	
113	        const cacheKey = 'auth_' + crypto.createHash('sha256').update(token).digest('hex').slice(0, 20);
114	        if (Object.prototype.hasOwnProperty.call(tokenCache, cacheKey)
115	            && tokenCache[cacheKey].exp >= Date.now()) {
116	            return tokenCache[cacheKey].claims;
117	        }
118	        try {
119	            const oidc = await getOidcConfig();
120	            // Always pin the issuer to the discovered IdP; enforce audience only when configured.
121	            // Without these, any signature-valid token from a provider that shares the JWKS would
122	            // be accepted.
123	            const verifyOpts = {};
124	            if (oidc.issuer) verifyOpts.issuer = oidc.issuer;
125	            if (tokenAudience) verifyOpts.audience = tokenAudience;
126	            const { payload } = await jwtVerify(token, await getJwks(), verifyOpts);
127	            // Enrich with userinfo — access tokens are minimal by OIDC convention, rich claims
128	            // (email, name, groups) live in the userinfo response. JWT payload wins on collisions
129	            // so verified fields stay authoritative.
130	            let claims = payload;
131	            try {
132	                const r = await httpGet(oidc.userinfo_endpoint, { 'Authorization': 'Bearer ' + token });
133	                if (r.status === 200 && r.body && typeof r.body === 'object') {
134	                    claims = Object.assign({}, r.body, payload);
135	                } else {
136	                    warn('MCP userinfo returned ' + r.status + ' — using JWT claims only');
137	                }
138	            } catch (e) {
139	                warn('MCP userinfo fetch failed: ' + e.message + ' — using JWT claims only');
140	            }
141	            const tokenExpMs = (typeof payload.exp === 'number') ? payload.exp * 1000 : Infinity;
142	            const cacheExp = Math.min(Date.now() + tokenTTL, tokenExpMs);
143	            cacheToken(cacheKey, { claims, exp: cacheExp });
144	            return claims;
145	        } catch (e) {
146	            warn('MCP token verify failed: ' + e.message);
147	            return null;
148	        }
149	    }
150	
151	    async function requireBearer(req, res) {
152	        const authHeader = req.headers['authorization'] || '';
153	        if (!authHeader.startsWith('Bearer ')) {
154	            res.set('WWW-Authenticate',
155	                `Bearer resource_metadata="${mcpServerUrl}/.well-known/oauth-protected-resource"`);
156	            res.status(401).json({ error: 'unauthorized' });
157	            return null;
158	        }
159	        const token  = authHeader.slice(7);
160	        const claims = await validateToken(token);
161	        if (!claims) {
162	            res.set('WWW-Authenticate',
163	                `Bearer error="invalid_token", resource_metadata="${mcpServerUrl}/.well-known/oauth-protected-resource"`);
164	            res.status(401).json({ error: 'invalid_token' });
165	            return null;
166	        }
167	        return claims;
168	    }
169	
170	    return {
171	        validateToken,
172	        requireBearer,
173	        getOidcConfig,
174	        clearCache: () => { tokenCache = {}; },
175	        cacheSize:  () => Object.keys(tokenCache).length
176	    };
177	}
178	
179	module.exports = { createMcpAuth, secretEqual };
