2	// Topic / message-field filter matching for hal2Thing. Pure MQTT wildcard matching, topic
3	// prefix resolution, per-field matchers and the and/or filter runner — extracted so routing
4	// logic can be unit-tested. The message-property getter is injected so the module has no
5	// Node-RED dependency.
6	
7	function matchTopic(ts, t) {
8	    if (ts == '#') {
9	        return true;
10	    }
11	    /* The following allows shared subscriptions (as in MQTT v5)
12	       http://docs.oasis-open.org/mqtt/mqtt/v5.0/cs02/mqtt-v5.0-cs02.html#_Toc514345522
13	       4.8.2 describes shares like $share/{ShareName}/{filter}. */
14	    else if (ts.startsWith('$share')) {
15	        ts = ts.replace(/^\$share\/[^#+/]+\/(.*)/g, '$1');
16	    }
17	    var re = new RegExp('^' + ts.replace(/([\[\]\?\(\)\\\\$\^\*\.|])/g, '\\$1').replace(/\+/g, '[^/]+').replace(/\/#$/, '(\/.*)?') + '$');
18	    return re.test(t);
19	}
20	
21	function fixTopic(topicstring, configuredTopic) {
22	    var topic = topicstring;
23	    if (topic.startsWith('.')) {
24	        topic = topic.replace('.', configuredTopic);
25	    }
26	    if (topic.startsWith('/')) {
27	        topic = configuredTopic + topic;
28	    }
29	    return topic;
30	}
31	
32	// a = msg value, b = filter pattern
33	var TOPIC_MATCHERS = {
34	    'str':        function (a, b) { return a === b; },
35	    're':         function (a, b) { return (new RegExp(b)).test(a + ''); },
36	    'mqtt':       function (a, b) { return matchTopic(b, a); },
37	    'StrStart':   function (a, b) { return (a + '').startsWith(b); },
38	    'StrEnd':     function (a, b) { return (a + '').endsWith(b); },
39	    'StrContain': function (a, b) { return (a + '').includes(b); }
40	};
41	
42	// Run a list of field filters against a message. `getProp(msg, field)` reads the message
43	// property (inject RED.util.getMessageProperty). mode 'or' matches if any filter passes,
44	// otherwise all must pass. Empty/absent filters always match.
45	function applyFilters(msg, filters, mode, topicPrefix, getProp) {
46	    if (!filters || filters.length === 0) return true;
47	    for (var i = 0; i < filters.length; i++) {
48	        var f = filters[i];
49	        var val = getProp(msg, f.field);
50	        var filterVal = f.value;
51	        if (f.field === 'topic' && f.matchType === 'str' && topicPrefix) {
52	            filterVal = fixTopic(filterVal, topicPrefix);
53	        }
54	        var fn = TOPIC_MATCHERS[f.matchType];
55	        var matched = fn ? fn(val, filterVal) : false;
56	        if (mode === 'or') { if (matched) return true; }
57	        else               { if (!matched) return false; }
58	    }
59	    return mode !== 'or';
60	}
61	
62	module.exports = { matchTopic, fixTopic, TOPIC_MATCHERS, applyFilters };
