'use strict';
// Smoke test: instantiate hal2EventHandler against a mocked RED and exercise the
// OAuth endpoints directly — verifies public-client DCR, metadata auth methods,
// and prefix-consistent discovery URLs without a running Node-RED.

const EventEmitter = require('events');
const assert = require('node:assert');

function buildRED() {
    const routes = { get: {}, post: {} };
    const httpNode = {
        get : (path, ...fns) => { routes.get[path]  = fns; },
        post: (path, ...fns) => { routes.post[path] = fns; },
        _router: { stack: [] }
    };
    const RED = {
        httpNode,
        events: { on() {}, once() {}, removeListener() {} },
        nodes: {
            createNode(node, config) { node.id = config.id; },
            registerType(name, ctor) { RED._types = RED._types || {}; RED._types[name] = ctor; },
            getNode() { return null; },
            eachNode() {}
        },
        util: { getMessageProperty: () => undefined }
    };
    return { RED, routes };
}

async function call(routes, method, path, body) {
    const fns = routes[method][path];
    if (!fns) return { code: 404, body: null, missing: true };
    const req = { body: body || {}, headers: {}, ip: '203.0.113.7' };
    const res = {
        code: null, body: null, hdrs: {},
        set(k, v)  { this.hdrs[k] = v; return this; },
        status(c)  { this.code = c;    return this; },
        json(b)    { this.body = b;    return this; },
        send(b)    { this.body = b;    return this; }
    };
    for (let i = 0; i < fns.length - 1; i++) {
        let next = false;
        fns[i](req, res, () => { next = true; });
        if (!next) return res;
    }
    await fns[fns.length - 1](req, res);
    return res;
}

function makeHandler(config, credentials) {
    const { RED, routes } = buildRED();
    require('/Users/fredrikfurtenbach/repos/private/node-red-contrib-hal2/core/eventhandler.js')(RED);
    const node = new EventEmitter();
    node.log = node.warn = node.debug = node.error = () => {};
    node.status = () => {};
    node.credentials = credentials;
    RED._types['hal2EventHandler'].call(node, config);
    return { routes };
}

const baseConfig = {
    id: 'eh1', name: 'test', maxlisteners: '100',
    mcpEnabled: true,
    mcpServerUrl: 'https://mcp.example.com/',   // trailing slash on purpose
    httpPathPrefix: '',
    pocketidUrl: '',                            // no discovery in this test
    mcpRedirectUris: 'https://claude.ai/api/mcp/auth_callback'
};

(async () => {
    // ── 1. Public client: no secret configured ────────────────────────────────
    {
        const { routes } = makeHandler(baseConfig, { pocketidClientId: 'hal2-client' });
        const reg = await call(routes, 'post', '/oauth/register', { redirect_uris: ['https://claude.ai/api/mcp/auth_callback'] });
        assert.strictEqual(reg.code, 201);
        assert.strictEqual(reg.body.client_id, 'hal2-client');
        assert.strictEqual('client_secret' in reg.body, false, 'no secret must be disclosed');
        assert.strictEqual(reg.body.token_endpoint_auth_method, 'none');

        const as = await call(routes, 'get', '/.well-known/oauth-authorization-server');
        assert.deepStrictEqual(as.body.token_endpoint_auth_methods_supported, ['none']);
        assert.strictEqual(as.body.issuer, 'https://mcp.example.com');            // trailing slash stripped
        assert.strictEqual(as.body.registration_endpoint, 'https://mcp.example.com/oauth/register');

        const pr = await call(routes, 'get', '/.well-known/oauth-protected-resource');
        assert.deepStrictEqual(pr.body.authorization_servers, ['https://mcp.example.com']);
        console.log('ok  public client: no secret in DCR, auth method none');
    }

    // ── 2. Confidential client: secret configured (legacy behavior kept) ─────
    {
        const { routes } = makeHandler(baseConfig, { pocketidClientId: 'hal2-client', pocketidClientSecret: 's3cr3t' });
        const reg = await call(routes, 'post', '/oauth/register', {});
        assert.strictEqual(reg.body.client_secret, 's3cr3t');
        assert.strictEqual(reg.body.token_endpoint_auth_method, 'client_secret_post');

        const as = await call(routes, 'get', '/.well-known/oauth-authorization-server');
        assert.deepStrictEqual(as.body.token_endpoint_auth_methods_supported, ['client_secret_post', 'none']);
        console.log('ok  confidential client: legacy DCR behavior unchanged');
    }

    // ── 3. Prefix: both well-known forms served, URLs include the prefix ─────
    {
        const cfg = Object.assign({}, baseConfig, { httpPathPrefix: '/hal' });
        const { routes } = makeHandler(cfg, { pocketidClientId: 'hal2-client' });

        for (const p of ['/hal/.well-known/oauth-authorization-server', '/.well-known/oauth-authorization-server/hal']) {
            const as = await call(routes, 'get', p);
            assert.strictEqual(as.missing, undefined, 'route must exist: ' + p);
            assert.strictEqual(as.body.issuer, 'https://mcp.example.com/hal');
            assert.strictEqual(as.body.registration_endpoint, 'https://mcp.example.com/hal/oauth/register');
        }
        for (const p of ['/hal/.well-known/oauth-protected-resource', '/.well-known/oauth-protected-resource/hal']) {
            const pr = await call(routes, 'get', p);
            assert.strictEqual(pr.missing, undefined, 'route must exist: ' + p);
            assert.deepStrictEqual(pr.body.authorization_servers, ['https://mcp.example.com/hal']);
        }
        console.log('ok  prefix: both well-known forms served, consistent URLs');
    }

    // ── 4. DCR still rejects non-allowlisted redirect URIs ────────────────────
    {
        const { routes } = makeHandler(baseConfig, { pocketidClientId: 'hal2-client' });
        const reg = await call(routes, 'post', '/oauth/register', { redirect_uris: ['https://evil.example.com/cb'] });
        assert.strictEqual(reg.code, 400);
        assert.strictEqual(reg.body.error, 'invalid_redirect_uri');
        console.log('ok  DCR: non-allowlisted redirect_uris still rejected');
    }

    console.log('\nAll OAuth smoke checks passed.');
})().catch(e => { console.error('FAILED:', e.message); process.exit(1); });

